"""Export the complete filtered stock consultation, without posting movements."""

HTML = '''<div class="files-actions"><button id="stock-export" type="button" disabled>Descargar stock filtrado (CSV)</button></div><p id="stock-export-notice" role="status"></p>'''

FILTER_JS = r'''
function stockFilteredArticles(){if(state?.info?.dataset_id!==$('dataset').value)return [];const query=$('stock-search').value.trim().toLocaleLowerCase('es'),provider=$('stock-provider').value,onlyAlerts=$('stock-alert-only').checked,order=$('stock-order').value,rank={EMPTY:0,LOW:1,LIMIT:2,UNKNOWN:3,OK:4};return state.articles.filter(a=>{const sources=state.stock_metrics?.[a.article_id]?.suppliers||[];return stockFamilyMatches(a)&&(!stockExactArticle||a.article_id===stockExactArticle)&&(!query||[a.article_id,a.description,stockArticleFamily(a),...sources.map(s=>s.name+' '+s.supplier_id)].join(' ').toLocaleLowerCase('es').includes(query))&&(!provider||sources.some(s=>s.supplier_id===provider))&&(!onlyAlerts||['EMPTY','LOW','LIMIT'].includes(state.stock_minimums[a.article_id].status))}).sort((a,b)=>(order==='PRIORITY'?(rank[state.stock_minimums[a.article_id].status]-rank[state.stock_minimums[b.article_id].status]):0)||(order==='NAME'?(a.description||a.article_id).localeCompare(b.description||b.article_id,'es'):0)||a.article_id.localeCompare(b.article_id,'es'));}
'''

JS = r'''
function stockCSVCell(value,numeric=false){let text=String(value??'');if(!(numeric&&/^-?[0-9]+(?:,[0-9]+)?$/.test(text))&&(/^[\s\u0000-\u001f]*[=+@-]/.test(text)||/^[\t\r\n]/.test(text)))text="'"+text;return '"'+text.replaceAll('"','""')+'"'}
function stockCSVNumber(value){return value===null||value===undefined||value===''?'':/^-?[0-9]+(?:\.[0-9]+)?$/.test(String(value))?String(value).replace('.',','):''}
function stockCSV(){
 if(state?.info?.dataset_id!==$('dataset').value)throw Error('Espera a que termine la carga de la empresa seleccionada.');const articles=stockFilteredArticles();if(!articles.length)throw Error('No hay artículos que coincidan con los filtros.');
 const rows=[['Empresa','Código de empresa','Versión de datos','Corte documental','Naturaleza del expediente','SKU','Descripción','Familia','Proveedores documentados','Físico','Reservado','Disponible','Unidad de inventario / catálogo','Fecha de inventario','Naturaleza del inventario','Mínimo aplicado','Unidad del mínimo','Origen del mínimo','Aviso de mínimo','Archivo de inventario','Fila de inventario','Estado del inventario seleccionado']];
 articles.forEach(article=>{const inventory=state.inventory?.[article.article_id],minimum=state.stock_minimums?.[article.article_id],suppliers=state.stock_metrics?.[article.article_id]?.suppliers||[];rows.push([state.info.company.legal_name,state.info.company.company_id,state.info.dataset_id,stockDate(state.info.as_of_date),state.data_status?.dataset_id===state.info.dataset_id?state.data_status.material_nature||'':'',article.article_id,article.description,stockArticleFamily(article),suppliers.map(s=>s.name+' / '+s.supplier_id).join(' | '),stockCSVNumber(inventory?.physical),stockCSVNumber(inventory?.reserved),stockCSVNumber(inventory?.available),inventory?.unit||article.unit_as_documented||'',inventory?.as_of_date?stockDate(inventory.as_of_date):'',inventory?.material_nature||'',stockCSVNumber(minimum?.value),minimum?.unit||'',({AUTOMATIC:'Automático',MANUAL:'Manual'})[minimum?.source]||'Sin configurar',minimum?.label||'',inventory?.source_ref?.filename||'',inventory?.source_ref?.source_row??'',state.selected_inventory?.status||''])});
 return {text:'\ufeff'+rows.map((row,rowIndex)=>row.map((value,index)=>stockCSVCell(value,rowIndex>0&&[9,10,11,15,20].includes(index))).join(';')).join('\r\n')+'\r\n',count:articles.length};
}
$('stock-export').onclick=()=>{let url;try{const result=stockCSV(),blob=new Blob([result.text],{type:'text/csv;charset=utf-8'}),link=document.createElement('a');url=URL.createObjectURL(blob);link.href=url;link.download='EIOS_Stock_'+String(state.info.company.company_id||'empresa').replace(/[^a-zA-Z0-9_-]/g,'_')+'_'+state.info.as_of_date+'.csv';document.body.append(link);link.click();link.remove();$('stock-export-notice').textContent='Descargados '+stockNumber(result.count)+' artículos: todos los resultados filtrados, incluidas las demás páginas. Mínimos aplicados; los cambios sin guardar no se exportan. Los campos vacíos significan dato ausente.'}catch(error){$('stock-export-notice').textContent=error.message}finally{if(url)setTimeout(()=>URL.revokeObjectURL(url),1000)}};
'''
